const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const banamepe = ee.Geometry.Point([140.5, -5.9]); // Approximate location of Banamepe
  const aoi = banamepe.buffer(10000); // 10km buffer around Banamepe

  const nov2002_start = '2002-11-01';
  const nov2002_end = '2002-11-30';
  const nov2019_start = '2019-11-01';
  const nov2019_end = '2019-11-30';

  // 2. Data Acquisition - Using MODIS Vegetation Indices for consistent data
  const modis2002 = ee.ImageCollection('MODIS/061/MOD13Q1')
    .filterDate(nov2002_start, nov2002_end)
    .filterBounds(aoi);

  const modis2019 = ee.ImageCollection('MODIS/061/MOD13Q1')
    .filterDate(nov2019_start, nov2019_end)
    .filterBounds(aoi);

  // Check collection sizes
  const count2002 = modis2002.size().getInfo();
  const count2019 = modis2019.size().getInfo();

  console.log(`2002 Images: ${count2002}`);
  console.log(`2019 Images: ${count2019}`);

  if (count2002 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NDVI for each period
  const ndvi2002 = modis2002.select('NDVI').mean().multiply(0.0001); // Scale factor
  const ndvi2019 = modis2019.select('NDVI').mean().multiply(0.0001);

  // Count valid pixels
  const count2002_pixels = ndvi2002.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2019_pixels = ndvi2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`2002 Valid Pixels: ${count2002_pixels}`);
  console.log(`2019 Valid Pixels: ${count2019_pixels}`);

  if (count2002_pixels === 0 || count2019_pixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean NDVI values
  const mean2002 = ndvi2002.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const mean2019 = ndvi2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`2002 Mean NDVI: ${mean2002 ? mean2002.toFixed(3) : 'null'}`);
  console.log(`2019 Mean NDVI: ${mean2019 ? mean2019.toFixed(3) : 'null'}`);

  // 5. Validation & Final Answer
  if (mean2002 === null || mean2019 === null || 
      isNaN(mean2002) || isNaN(mean2019) ||
      mean2002 > 1 || mean2019 > 1 || mean2002 < -1 || mean2019 < -1) {
    console.log("<answer>C3</answer>");
  } else if (mean2019 < mean2002) {
    console.log("Forest cover decreased (NDVI lower in 2019)");
    console.log("<answer>A</answer>");
  } else {
    console.log("Forest cover did not decrease");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
